/**
 * Provider table — the single place a provider is declared. `key` names the
 * LOGOS entry (src/lib/logos.ts, generated by `bun run logos` from `icon`),
 * `needles` are lower-case substrings matched against the model id; first
 * row with a hit wins, so hosts precede the families they serve and
 * `openrouter` is never a needle (every OpenRouter id contains it).
 */
export interface Provider { key: string; icon: string; needles: string[] }

